mapper.select:
/* * isry.couns.stats.dscsnstats.mapper.ProblemSolvingStatsMapper.selectproblemSolvingStats */ SELECT AA.TTL_NM NM, /* 고민해결백과명칭 */ NVL(BB.CNT,0) CNT /* 댓글건수 */ FROM ( SELECT GRIEF_SLTN_ALKIOL_SN CD, /* 고민해결백과일련번호 */ GRIEF_SLTN_ALKIOL_THMA_SN SN, SQNCE_NO SQNCE, TTL_NM /* 제목명 */ FROM AYE410 ) AA, ( SELECT A.GRIEF_SLTN_ALKIOL_SN CD, COUNT(B.BBSCTT_ESNTAL_NO) CNT FROM AYE100 A , AYE110 B WHERE 1=1 AND A.BBSCTT_TYPE_SE_CD = #{bbscttTypeSeCd} AND A.BBSCTT_ESNTAL_NO = B.BBSCTT_ESNTAL_NO AND A.BBSCTT_TYPE_SE_CD = B.BBSCTT_TYPE_SE_CD
AND A.FRST_REG_DT >= TO_DATE(#{startDate} || '000000', 'YYYYMMDDHH24MISS') AND A.FRST_REG_DT <= TO_DATE(#{endDate} || '000000', 'YYYYMMDDHH24MISS')
AND A.DEL_YN = 'N' AND B.DEL_YN = 'N' GROUP BY A.GRIEF_SLTN_ALKIOL_SN ) BB WHERE AA.CD = BB.CD(+) ORDER BY AA.SN, AA.SQNCE
